import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"📥 下载管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/download.md","filePath":"guide/download.md","lastUpdated":1787147337000}'),l={name:"guide/download.md"};function i(s,a,n,d,h,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="📥-下载管理" tabindex="-1">📥 下载管理 <a class="header-anchor" href="#📥-下载管理" aria-label="Permalink to &quot;📥 下载管理&quot;">​</a></h1><h2 id="🔍-解析" tabindex="-1">🔍 解析 <a class="header-anchor" href="#🔍-解析" aria-label="Permalink to &quot;🔍 解析&quot;">​</a></h2><p>把 B 站链接（单视频 / 收藏夹 / 合集 / 多P）粘贴到输入框，点「解析」。</p><p>列表会一次性全部出现 —— 解析只获取标题、封面等列表信息，不逐个请求视频流， 所以又快又不容易触发风控；画质菜单因此显示完整档位，实际画质由下载时自动降级决定， 详见 <a href="/troubleshooting/quality-auto-downgrade.html">画质菜单与批量下载画质说明</a>。</p><p>解析完成后会自动展开最后一项的详情和封面预览；每一项也可以手动点「查看封面」和「详情」。</p><h2 id="☑️-勾选与下载选项" tabindex="-1">☑️ 勾选与下载选项 <a class="header-anchor" href="#☑️-勾选与下载选项" aria-label="Permalink to &quot;☑️ 勾选与下载选项&quot;">​</a></h2><ul><li>支持全选，合集 / 多P 会显示为分组，可整组勾选、展开查看；</li><li>下载选项（视频 / 音频 / 封面 / 字幕 / 弹幕、画质、视频编码、音质、音频格式）对<strong>同一批</strong> 勾选的视频统一生效 —— 想给不同视频用不同画质，分几批下载即可；</li><li>视频编码可选“自动（兼容优先）”或 AV1；自动模式保持内核默认选择与回退策略，主动选择 AV1 时优先下载 AV1 流，缺失时自动回退；</li><li>勾选封面时会将封面内嵌到媒体文件，并同时单独保存封面图片；</li><li>画质放心选高：视频不支持时自动降级到它的最高档，不会失败。</li></ul><h2 id="🚦-下载队列" tabindex="-1">🚦 下载队列 <a class="header-anchor" href="#🚦-下载队列" aria-label="Permalink to &quot;🚦 下载队列&quot;">​</a></h2><ul><li>队列<strong>串行执行</strong>：同一时刻只有一个任务在下载，其余安静地显示「排队中」。 这是刻意设计 —— 串行下载能显著降低触发 B 站风控的概率；</li><li>执行中的卡片有阶段行（解析中 / 写入附件 / 下载中 / 后处理中）和实时进度条 （百分比 · 已下载 / 总量 · 速率），并显示最终选择的视频/音频画质、编码、分辨率与转码动作；</li><li>排队和执行中的任务都可以取消，完成后可以直接「打开文件夹」。</li></ul><h2 id="🛰️-背后的-yutto-server" tabindex="-1">🛰️ 背后的 yutto server <a class="header-anchor" href="#🛰️-背后的-yutto-server" aria-label="Permalink to &quot;🛰️ 背后的 yutto server&quot;">​</a></h2><p>解析与下载由一个随应用自动启动 / 退出的常驻 yutto server 完成，平时无感。 如果出现「与 yutto server 的连接已断开」，到 设置 → 环境状态 一键重启即可： <a href="/troubleshooting/serve-restart.html">server 连接断开 / 启动失败</a>。</p>',11)])])}const p=e(l,[["render",i]]);export{_ as __pageData,p as default};
